// 1. Gather Context & Candidate Products from Supabase (ilike + prefix + pg_trgm fuzzy)
const axios = require('axios');
const SB = (typeof $env !== 'undefined' && $env.SUPABASE_URL) || (typeof process !== 'undefined' && process.env && process.env.SUPABASE_URL) || '';
const _SB_SVC = (typeof $env !== 'undefined' && ($env.SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_KEY)) || (typeof process !== 'undefined' && process.env && (process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY)) || '';
const _SB_ANON = (typeof $env !== 'undefined' && $env.SUPABASE_ANON_KEY) || (typeof process !== 'undefined' && process.env && process.env.SUPABASE_ANON_KEY) || '';
if (!_SB_SVC && _SB_ANON && typeof globalThis !== 'undefined' && !globalThis.__sbAnonFallbackWarned) { globalThis.__sbAnonFallbackWarned = true; if (typeof console !== 'undefined' && typeof console.warn === 'function') console.warn('[supabase-key] SUPABASE_SERVICE_ROLE_KEY / SUPABASE_SERVICE_KEY not set; falling back to SUPABASE_ANON_KEY'); }
const ANON = _SB_SVC || _SB_ANON;
const H = { apikey: ANON, Authorization: 'Bearer ' + ANON, 'Content-Type': 'application/json' };

const body = $json.body || $json;
const busqueda = String(body.p_busqueda || body.busqueda || body.query_normalizada || '').trim();
if (busqueda.length < 2) {
  return [];
}
const telefono = body.cliente_telefono || body.telefono || 'desconocido';
const contexto = body.contexto_conversacion || body.contexto || '';
const motivo = body.motivo || 'encontrados_cero';
const queryNorm = String(body.query_normalizada || busqueda).trim();

const normText = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const rawTokens = Array.isArray(body.query_tokens) && body.query_tokens.length
  ? body.query_tokens.map(normText)
  : normText(busqueda).split(/\s+/);
const palabras = [...new Set(rawTokens.filter(w => w && w.length >= 3))].slice(0, 6);

const candMap = new Map();
const addRows = (rows) => {
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (r && r.codigo_interno && !candMap.has(String(r.codigo_interno)) && candMap.size < 40) {
      candMap.set(String(r.codigo_interno), {
        codigo_interno: r.codigo_interno,
        descripcion: r.descripcion,
        precio_venta: r.precio_venta,
        existencia: r.existencia,
      });
    }
  }
};

try {
  const queries = [];
  if (palabras.length > 0) {
    const terms = new Set();
    for (const p of palabras) {
      terms.add(p);
