    }
    const orFilter = [...terms].map(t => 'descripcion.ilike.*' + encodeURIComponent(t) + '*').join(',');
    queries.push(
      axios.get(SB + '/rest/v1/productos?or=(' + orFilter + ')&select=codigo_interno,descripcion,precio_venta,existencia&order=existencia.desc.nullslast&limit=35', { headers: H, timeout: 4000 })
        .then(r => r.data).catch(() => [])
    );
  }
  if (queryNorm.length >= 3) {
    queries.push(
      axios.post(SB + '/rest/v1/rpc/buscar_fuzzy', { p_term: normText(queryNorm) }, { headers: H, timeout: 4000 })
        .then(r => r.data).catch(() => [])
    );
  }
