try {
  const resVoc = await axios.get(SB + '/rest/v1/catalogo_vocabulario?activo=eq.true&select=termino,canonico,categoria&limit=100', { headers: H, timeout: 3000 });
  vocabulario = resVoc.data || [];
} catch (e) {}

return [{
  json: {
    busqueda,
    query_normalizada: queryNorm,
    telefono,
    contexto,
    motivo,
    candidatos: [...candMap.values()],
    vocabulario_muestra: vocabulario.slice(0, 30)
  }
